using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B4PolishEnrich {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B4_LayoutPolish/";const string P="Assets/Afrer_Seconds/05.Model/Props/B4/";static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 static GameObject Place(string model,string name,Transform parent,Vector3 pos,Quaternion rot){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(P+model+".fbx"),parent);g.name=name;g.transform.localPosition=pos;g.transform.localRotation=rot;foreach(var mf in g.GetComponentsInChildren<MeshFilter>())mf.gameObject.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;foreach(var t in g.GetComponentsInChildren<Transform>()){PrefabUtility.RecordPrefabInstancePropertyModifications(t);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);}return g;}
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("B4 edit required");var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();if(ts.Any(t=>t.name.Contains("BenchPedestal")))throw new Exception("Already enriched");var plan=JObject.Parse(File.ReadAllText(H+"layout.json"));var records=new List<object>();int pedestals=0;
 foreach(var t in ts.Where(t=>t.gameObject.activeInHierarchy&&PrefabUtility.IsAnyPrefabInstanceRoot(t.gameObject))){var path=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject);if(!new[]{"BF_ResearchDesk.fbx","BF_AnalysisBench.fbx","BF_SensorWorkbench.fbx"}.Any(path.EndsWith))continue;float x=path.EndsWith("BF_ResearchDesk.fbx")?.63f:path.EndsWith("BF_AnalysisBench.fbx")?.85f:.75f;var g=Place("BP_BenchPedestal",t.name+"_BenchPedestal",t,new Vector3(x,0,-.025f),Quaternion.identity);pedestals++;records.Add(new{name=g.name,asset=P+"BP_BenchPedestal.fbx"});}
 foreach(string code in new[]{"E02","N01"}){var room=plan["rooms"].Single(r=>(string)r["id"]==code);var center=new Vector3((float)room["x"],-66,-(float)room["v"]);var parent=ts.Single(t=>t.name=="B4_"+code+"_ServiceAndDetail");var prefs=code=="E02"?new[]{new Vector3(0,0,1.7f),new Vector3(.8f,0,2.0f),new Vector3(-1,0,1.2f)}:new[]{new Vector3(-.6f,0,.6f),new Vector3(-1.5f,0,1.5f),new Vector3(.5f,0,1.5f)};GameObject added=null;
 foreach(var p in prefs){bool blocked=Physics.CheckBox(center+p+Vector3.up*1.1f,new Vector3(1.45f,1.02f,.95f),Quaternion.identity,~0,QueryTriggerInteraction.Ignore);if(blocked)continue;bool approach=new[]{-1,1}.All(side=>!Physics.CheckCapsule(center+p+new Vector3(0,.43f,side*1.5f),center+p+new Vector3(0,1.50f,side*1.5f),.40f,~0,QueryTriggerInteraction.Ignore));if(!approach)continue;added=Place("BP_CalibrationIsland","B4_"+code+"_CalibrationIsland",parent,p,Quaternion.identity);foreach(int side in new[]{-1,1})((JArray)plan["workspaces"]).Add(JObject.FromObject(new{name=added.name+(side<0?"_Rear":"_Front"),room=code,point=V(p+new Vector3(0,0,side*1.5f))}));records.Add(new{name=added.name,position=V(p),asset=P+"BP_CalibrationIsland.fbx"});break;}
 if(!added)throw new Exception("No clear bay "+code);}
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllText(H+"layout.json",plan.ToString());File.WriteAllText(H+"enrichment.json",JsonConvert.SerializeObject(records,Formatting.Indented));return new{pedestals,islands=2};}
}
